/**
 * Admin Controller — Dashboard stats, order management, customers, audit log.
 * Generated by BackendForge
 */
const adminService = require('../services/admin.service');
const { parsePagination, paginatedResponse } = require('../utils/pagination');

const adminController = {
  /**
   * GET /api/admin/dashboard — Revenue, order counts, pending shipments
   */
  async getDashboard(req, res, next) {
    try {
      const stats = await adminService.getDashboardStats();
      res.json({ success: true, data: stats });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/admin/account — Admin's own profile/details
   */
  async getAccount(req, res, next) {
    try {
      const account = await adminService.getAdminAccount(req.userId);
      res.json({ success: true, data: { account } });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/admin/orders — All orders with full customer details
   */
  async getAllOrders(req, res, next) {
    try {
      const pagination = parsePagination(req.query);
      const { status, paymentStatus, search } = req.query;
      const result = await adminService.getAllOrders(pagination, { status, paymentStatus, search });
      res.json({ success: true, ...paginatedResponse(result.orders, result.total, pagination) });
    } catch (error) { next(error); }
  },

  /**
   * PUT /api/admin/orders/:id/status — Update shipping status
   */
  async updateOrderStatus(req, res, next) {
    try {
      const order = await adminService.updateOrderStatus(req.params.id, req.body, req.user);
      res.json({ success: true, message: 'Order status updated', data: { order } });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/admin/cancellations — All cancelled orders
   */
  async getCancellations(req, res, next) {
    try {
      const pagination = parsePagination(req.query);
      const result = await adminService.getCancellations(pagination);
      res.json({ success: true, ...paginatedResponse(result.orders, result.total, pagination) });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/admin/customers — Customer list
   */
  async getCustomers(req, res, next) {
    try {
      const pagination = parsePagination(req.query);
      const result = await adminService.getCustomers(pagination, req.query.search);
      res.json({ success: true, ...paginatedResponse(result.customers, result.total, pagination) });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/admin/audit-log — Admin activity history
   */
  async getAuditLog(req, res, next) {
    try {
      const pagination = parsePagination(req.query);
      const result = await adminService.getAuditLog(pagination);
      res.json({ success: true, ...paginatedResponse(result.logs, result.total, pagination) });
    } catch (error) { next(error); }
  },
};

module.exports = adminController;
